#!/bin/bash
# The tools at the end run as ( ) subshell functions on purpose: their settings stay local.
# shellcheck disable=SC2030,SC2031
# SPDX-License-Identifier: GPL-3.0-or-later
# configure-misterplex.sh - the one MisterPlex entry in the MiSTer Scripts menu.
#
# GENERATED by scripts/build_scripts_menu.sh from scripts/menu/configure-misterplex.head.sh,
# scripts/configure-misterplex.sh (Settings), mister-db/misterplex_setup.sh (Setup / Repair)
# and scripts/uninstall-misterplex.sh (Uninstall). Edit those, then run
# scripts/build_scripts_menu.sh (writes packaging/Scripts/); tests/unit/test_scripts_menu.sh fails when stale.
#
# Menu (blue dialog look like the other MiSTer Scripts tools; plain numbered menu when
# dialog is missing):
#   1 Settings            the guided misterplex.conf editor
#   2 Restart MisterPlex  restart the running mode (Plex or Live TV)
#   3 Repair / Reinstall  re-run setup: linux/ helpers, settings file if missing, boot line
#   4 Uninstall           choose Uninstall (keep settings) or Purge, each confirms (default No)
# Plex <-> Live TV service switching is only in the core OSD (Service switch), not this menu.
# First run: when the boot line, the CA bundle or the AirPlay helper is missing, setup runs
# by itself before the menu opens (update_all/Downloader cannot run scripts).
#
# Non-interactive use (tests, ssh):
#   configure-misterplex.sh settings [configure flags]   e.g. settings -y --name tv
#   configure-misterplex.sh restart | repair | setup
#   configure-misterplex.sh uninstall --yes [--keep-core|--purge|--dry-run]
#   configure-misterplex.sh --selftest                    print the menu tree, check helpers
#   MPX_MENU_CHOICE=<key> picks one menu item without a terminal; MPX_MENU_UI=text|dialog.
# The dialog screen is drawn on the terminal found from stdin (tty, else /dev/tty), so the
# blue dialogs also work inside $(...) captures. Restart and Repair log status to
# /tmp/misterplex-menu.log and the menu can show the last one the next time it opens.
set -u

MENU_PROG=configure-misterplex.sh
ROOT="${ROOT:-}"
FAT="$ROOT/media/fat"
MODE_SH="${MPX_MODE_SH:-$FAT/misterplex/bin/misterplex_mode.sh}"
TITLE="MisterPlex"
MENU_LOG="${MPX_MENU_LOG:-$ROOT/tmp/misterplex-menu.log}"   # RAM on the MiSTer; no SD writes
MENU_LAST="$MENU_LOG.last"                                    # one line, shown once in the menu

menu_say() { printf '%s\n' "$MENU_PROG: $*"; }
menu_log() { { printf '%s %s\n' "$(date '+%Y-%m-%d %H:%M:%S' 2>/dev/null)" "$*" >> "$MENU_LOG"; } 2>/dev/null || true; }

# key|label, in menu order.
MENU_ITEMS='settings|Settings
restart|Restart MisterPlex
repair|Repair / Reinstall
uninstall|Uninstall'

# The terminal the dialog screen is drawn on. Found from stdin (the Scripts console), not
# stdout: k=$(menu_choose) and v=$(menu_radiolist ...) turn stdout into a pipe, and the old
# [ -t 1 ] test then dropped every captured screen to the text menu.
mpx_ui_tty() {
  if [ -n "${MPX_UI_TTY:-}" ]; then printf '%s\n' "$MPX_UI_TTY"; return 0; fi
  [ -t 0 ] || return 1
  _t=$(tty 2>/dev/null) || _t=""
  case "$_t" in /dev/*) if [ -w "$_t" ]; then printf '%s\n' "$_t"; return 0; fi ;; esac
  if (: > /dev/tty) 2>/dev/null; then echo /dev/tty; return 0; fi
  return 1
}

use_dialog() {
  case "${MPX_MENU_UI:-}" in
    text) return 1 ;;
    dialog) return 0 ;;
  esac
  command -v dialog >/dev/null 2>&1 && [ -t 0 ] && mpx_ui_tty >/dev/null
}

# Every dialog call: the screen goes to the terminal, the answer (dialog writes it on
# stderr) comes back on stdout, so callers can capture it with $(dlg ...).
dlg() {
  _tty=$(mpx_ui_tty) || _tty=/dev/null
  # shellcheck disable=SC2069 # intended: answer (stderr) -> caller's stdout, screen -> tty
  dialog --backtitle "$TITLE" "$@" 2>&1 > "$_tty"
}

# Show a message and wait (dialog msgbox, or plain text + Enter).
menu_msg() {
  if use_dialog; then
    dlg --title "$TITLE" --msgbox "$1" 12 60
  else
    printf '\n%b\n' "$1"
    if [ -t 0 ]; then printf 'Press Enter to continue. '; read -r _ || true; fi
  fi
}

# Yes/No question, default No. MPX_MENU_YES=1 answers yes (tests).
menu_yesno() {
  [ "${MPX_MENU_YES:-0}" = 1 ] && return 0
  if use_dialog; then
    dlg --title "$TITLE" --defaultno --yesno "$1" 10 60 >/dev/null
    return
  fi
  [ -t 0 ] || return 1
  printf '%s [y/N] ' "$1"
  read -r ans || return 1
  case "$ans" in y|Y|yes|YES|Yes) return 0 ;; esac
  return 1
}

# Short status line (not a Done msgbox). Also logged; the menu shows the last one when it opens.
menu_status() {
  printf '%s\n' "$MENU_PROG: $*"
  menu_log "$*"
  { printf '%s\n' "$*" > "$MENU_LAST"; } 2>/dev/null || true
}

# Short "working" box that does not wait (dialog infobox, or a plain line).
menu_info() {
  if use_dialog; then dlg --title "$TITLE" --infobox "$1" 7 64 >/dev/null || true
  else printf '%b\n' "$1"; fi
}

# Input box. Prints the value on stdout (empty cancel). Returns 1 on cancel.
menu_inputbox() {
  if use_dialog; then
    dlg --title "$TITLE" --inputbox "$1" 10 60 "$2"
    return
  fi
  [ -t 0 ] || return 1
  printf '%s [%s]: ' "$1" "$2" >&2
  read -r ans || return 1
  printf '%s\n' "${ans:-$2}"
}

# Radiolist. $1 = prompt, then tag label on/off triples. Prints the selected tag.
menu_radiolist() {
  prompt=$1; shift
  if use_dialog; then
    dlg --title "$TITLE" --no-tags --radiolist "$prompt" 15 60 8 "$@"
    return
  fi
  [ -t 0 ] || return 1
  printf '%s\n' "$prompt" >&2
  n=0
  selected=""
  while [ $# -ge 3 ]; do
    n=$((n + 1))
    lab=$2; on=$3
    eval "rl_$n=\$1"
    shift 3
    cur=""
    [ "$on" = on ] && cur=" *"
    printf '  %s) %s%s\n' "$n" "$lab" "$cur" >&2
  done
  printf 'Choose 1-%s: ' "$n" >&2
  read -r pick || return 1
  case "$pick" in ''|*[!0-9]*|0) return 1 ;; esac
  [ "$pick" -le "$n" ] || return 1
  eval "selected=\$rl_$pick"
  printf '%s\n' "$selected"
}

# Print the chosen key on stdout; empty = quit.
menu_choose() {
  if [ -n "${MPX_MENU_CHOICE:-}" ]; then printf '%s\n' "$MPX_MENU_CHOICE"; return; fi
  # The last status line (e.g. after Restart or Repair), shown once.
  _last=""
  if [ -f "$MENU_LAST" ]; then _last=$(head -n 1 "$MENU_LAST" 2>/dev/null); rm -f -- "$MENU_LAST" 2>/dev/null || true; fi
  if use_dialog; then
    set --
    while IFS='|' read -r k l; do set -- "$@" "$k" "$l"; done <<MENU
$MENU_ITEMS
MENU
    _prompt="Choose an option"
    [ -z "$_last" ] || _prompt="Last: $_last\n\nChoose an option"
    dlg --title "$TITLE" --no-tags --cancel-label "Exit" \
      --menu "$_prompt" 16 60 4 "$@" || true
    return
  fi
  [ -t 0 ] || return 0
  n=0
  printf '\n%s\n\n' "$TITLE" >&2
  [ -z "$_last" ] || printf 'Last: %s\n\n' "$_last" >&2
  while IFS='|' read -r _k l; do n=$((n + 1)); printf '  %s) %s\n' "$n" "$l" >&2; done <<MENU
$MENU_ITEMS
MENU
  printf '  0) Exit\n\nChoose 0-%s: ' "$n" >&2
  read -r pick || return 0
  case "$pick" in ''|*[!0-9]*|0) return 0 ;; esac
  printf '%s\n' "$MENU_ITEMS" | sed -n "${pick}p" | cut -d'|' -f1
}

daemon_running() { # any misterplexd or misterplexd-spelunkr process
  for c in "$ROOT"/proc/[0-9]*/cmdline; do
    [ -r "$c" ] || continue
    if tr '\0' ' ' < "$c" 2>/dev/null | grep -Eq '(^|/)misterplexd(-spelunkr)?( |$)'; then return 0; fi
  done
  return 1
}

current_mode() { # spelunkr when the Live TV daemon runs, else plex
  for c in "$ROOT"/proc/[0-9]*/cmdline; do
    [ -r "$c" ] || continue
    if tr '\0' ' ' < "$c" 2>/dev/null | grep -Eq '(^|/)misterplexd-spelunkr( |$)'; then echo spelunkr; return; fi
  done
  echo plex
}

mpx_restart() {
  m=$(current_mode)
  if [ ! -f "$MODE_SH" ]; then
    menu_status "Restart failed: mode helper is missing ($MODE_SH)."
    return 1
  fi
  menu_say "restarting MisterPlex ($m)"
  MPX_CORE_MANUAL_ONLY=1 sh "$MODE_SH" "--$m"
  rc=$?
  if [ "$rc" = 0 ]; then
    menu_status "Restarted MisterPlex ($m)."
  else
    menu_status "Restart MisterPlex failed (exit $rc)."
  fi
  return "$rc"
}

# The menu's signal traps: an interactive run restores fbcon and exits 129/130/143; a
# subcommand run keeps the shell defaults. Used at start and to put them back after a step
# that changed them (repair).
mpx_traps_rearm() {
  if [ "${MPX_MENU_INTERACTIVE:-0}" = 1 ]; then
    trap 'mpx_fbcon_restore; exit 129' HUP
    trap 'mpx_fbcon_restore; exit 130' INT
    trap 'mpx_fbcon_restore; exit 143' TERM
  else
    trap - HUP INT TERM
  fi
}

# PID and every descendant, parent first (ps -o pid,ppid works on busybox and procps).
mpx_proc_tree() {
  echo "$1"
  for _c in $(ps -o pid,ppid 2>/dev/null | awk -v p="$1" 'NR > 1 && $2 == p { print $1 }'); do
    mpx_proc_tree "$_c"
  done
}

# Signal during Repair: stop the background setup (it ignores SIGINT as an async job, so
# Ctrl-C alone leaves it running), restart the daemon in the mode it was in, report, exit.
mpx__repair_abort() { # exit-code
  trap '' HUP INT TERM
  if [ -n "${_pid:-}" ]; then
    # shellcheck disable=SC2046 # one PID per word
    kill -TERM $(mpx_proc_tree "$_pid") 2>/dev/null || true
    wait "$_pid" 2>/dev/null || true
    _pid=""
  fi
  if [ -z "$_was" ]; then
    menu_status "Repair interrupted. MisterPlex was not running before, so it was not started."
  elif [ ! -f "$MODE_SH" ]; then
    menu_status "Repair interrupted; restart failed: mode helper is missing ($MODE_SH)."
  else
    case "$_was" in spelunkr) _wl="Live TV" ;; *) _wl="Plex" ;; esac
    if MPX_CORE_MANUAL_ONLY=1 sh "$MODE_SH" "--$_was" >> "$MENU_LOG" 2>&1 < /dev/null; then
      menu_status "Repair interrupted. MisterPlex restarted ($_wl)."
    else
      menu_status "Repair interrupted; restarting MisterPlex ($_wl) failed. Choose Repair again."
    fi
  fi
  mpx_fbcon_restore
  exit "$1"
}

# Repair / first-run setup with progress, then the daemon back in the mode it was in
# (setup stops it). Prints ok or failed; returns setup's status (or the restart's).
mpx_repair() {
  _was=""; _pid=""
  if daemon_running; then _was=$(current_mode); fi
  # Ctrl-C / hangup / TERM mid-repair (N1): stop the setup job and put the daemon back in
  # the mode it was in (setup stops it first), then exit like the menu does.
  trap 'mpx__repair_abort 129' HUP
  trap 'mpx__repair_abort 130' INT
  trap 'mpx__repair_abort 143' TERM
  if use_dialog && [ "${MPX_MENU_INTERACTIVE:-0}" = 1 ]; then
    _rlog="$ROOT/tmp/misterplex-repair.log"
    mkdir -p "$ROOT/tmp" 2>/dev/null || true
    : > "$_rlog" 2>/dev/null || _rlog=/dev/null
    # Background on purpose: set -e inside the wrapped setup still applies (R2), and the
    # menu shows the latest setup line and elapsed time while it runs (it can take ~40 s).
    mpx__setup > "$_rlog" 2>&1 &
    _pid=$!
    _s=0
    while kill -0 "$_pid" 2>/dev/null; do
      _l=$(tail -n 1 "$_rlog" 2>/dev/null | sed 's/^misterplex_setup.sh: //' | cut -c1-58)
      menu_info "Repairing MisterPlex... ${_s}s\n\n$_l"
      sleep 1; _s=$((_s + 1))
    done
    wait "$_pid"; _rc=$?
    _pid=""
    [ "$_rlog" = /dev/null ] || cat "$_rlog" >> "$MENU_LOG" 2>/dev/null || true
  else
    # wait is interruptible; a foreground setup would defer traps until it finished.
    mpx__setup &
    _pid=$!
    wait "$_pid"; _rc=$?
    _pid=""
  fi
  mpx_traps_rearm
  if [ "$_rc" != 0 ]; then
    menu_status "Repair failed (exit $_rc). MisterPlex was not restarted."
    return "$_rc"
  fi
  if [ -z "$_was" ]; then
    menu_status "Repair ok. MisterPlex was not running before, so it was not started (it starts at boot)."
    return 0
  fi
  if [ ! -f "$MODE_SH" ]; then
    menu_status "Repair ok, but restart failed: mode helper is missing ($MODE_SH)."
    return 1
  fi
  case "$_was" in spelunkr) _wl="Live TV" ;; *) _wl="Plex" ;; esac
  menu_info "Repair ok. Restarting MisterPlex ($_wl)..."
  if [ "${MPX_MENU_INTERACTIVE:-0}" = 1 ]; then
    MPX_CORE_MANUAL_ONLY=1 sh "$MODE_SH" "--$_was" >> "$MENU_LOG" 2>&1 < /dev/null
  else
    MPX_CORE_MANUAL_ONLY=1 sh "$MODE_SH" "--$_was"
  fi
  _rc=$?
  if [ "$_rc" = 0 ]; then menu_status "Repair ok. MisterPlex restarted ($_wl)."
  else menu_status "Repair ok, but restarting MisterPlex ($_wl) failed (exit $_rc)."; fi
  return "$_rc"
}

# Framebuffer console. With fbcon unbound (bind=0) a Scripts launch is black on HDMI.
# The interactive menu binds it for its own run and puts back exactly what it found.
FBCON_RESTORE=""
mpx_fbcon_bind() {
  [ "${MPX_MENU_FBCON:-1}" = 1 ] || return 0
  for _v in "$ROOT"/sys/class/vtconsole/vtcon[0-9]*; do
    [ -f "$_v/bind" ] || continue
    grep -qs 'frame buffer' "$_v/name" || continue
    [ "$(cat "$_v/bind" 2>/dev/null)" = 0 ] || continue
    if { echo 1 > "$_v/bind"; } 2>/dev/null; then
      FBCON_RESTORE="$FBCON_RESTORE
$_v/bind"
    fi
  done
}
mpx_fbcon_restore() {
  [ -n "$FBCON_RESTORE" ] || return 0
  printf '%s\n' "$FBCON_RESTORE" | while IFS= read -r _b; do
    [ -n "$_b" ] || continue
    { echo 0 > "$_b"; } 2>/dev/null || true
  done
  FBCON_RESTORE=""
}

needs_setup() { # first run after update_all, or a half-finished install
  [ -f "$FAT/misterplex/bin/misterplexd-boot-rc3.sh" ] || return 1   # nothing installed: nothing to finish
  grep -qs 'misterplexd-boot-rc3.sh' "$FAT/linux/user-startup.sh" || return 0
  # Missing linux/ destinations need setup even when misterplex/linux/ staging
  # is absent (a tar install writes dests only, or dests were deleted later).
  [ -f "$FAT/linux/misterplex-cacert.pem" ] || return 0
  [ -f "$FAT/linux/airplay/airplay_xcode.py" ] || return 0
  return 1
}

menu_selftest() {
  echo "$TITLE menu:"
  n=0
  while IFS='|' read -r k l; do n=$((n + 1)); printf '  %s) %-20s [%s]\n' "$n" "$l" "$k"; done <<MENU
$MENU_ITEMS
MENU
  if command -v dialog >/dev/null 2>&1; then echo "ui: dialog"; else echo "ui: text (dialog not found)"; fi
  [ -f "$MODE_SH" ] && echo "mode helper: $MODE_SH" || echo "mode helper: missing ($MODE_SH)"
  if needs_setup; then echo "setup: needed"; else echo "setup: done or not installed"; fi
}

run_item() { # key [args]
  k=$1; shift
  case "$k" in
    settings) MPX_SETTINGS_CANCEL_RC=75 mpx__settings "$@" ;;
    restart) mpx_restart ;;
    repair|setup) mpx_repair ;;
    uninstall)
      if [ "${1:-}" = --yes ]; then
        shift
        mpx__uninstall "$@"
        return
      fi
      # Uninstall flow: choose keep-settings vs purge, each with its own confirm (default No).
      pick=""
      if use_dialog; then
        pick=$(dlg --title "$TITLE" --no-tags --cancel-label "Cancel" \
          --menu "Uninstall MisterPlex" 13 62 3 \
          uninstall "Uninstall (keep your settings)" \
          purge "Purge (also remove settings and user data)") || pick=""
      elif [ -t 0 ]; then
        printf '\nUninstall MisterPlex\n\n  1) Uninstall (keep your settings)\n  2) Purge (also remove settings and user data)\n  0) Cancel\n\nChoose 0-2: ' >&2
        read -r _uans || _uans=0
        case "$_uans" in 1) pick=uninstall ;; 2) pick=purge ;; *) pick="" ;; esac
      fi
      case "$pick" in
        uninstall)
          if ! menu_yesno "Remove MisterPlex from this MiSTer? Your settings will be kept."; then
            menu_say "uninstall cancelled"; return 75
          fi
          mpx__uninstall "$@" ;;
        purge)
          if ! menu_yesno "Remove MisterPlex AND your settings, identity, and backups? This cannot be undone."; then
            menu_say "purge cancelled"; return 75
          fi
          mpx__uninstall --purge "$@" ;;
        *) menu_say "uninstall cancelled"; return 75 ;;
      esac
      ;;
    quit|exit|'') return 0 ;;
    *) menu_say "unknown choice: $k"; return 2 ;;
  esac
}

menu_main() {
  case "${1:-}" in
    --selftest) menu_selftest; return ;;
    -h|--help) sed -n '/^# configure-misterplex.sh - /,/^#   MPX_MENU_CHOICE/p' "$0" | sed 's/^# \{0,1\}//'; return ;;
  esac
  # Interactive menu (no subcommand, no MPX_MENU_CHOICE, a terminal on stdin): bind the
  # framebuffer console for this run when it was unbound, and restore it on every exit.
  MPX_MENU_INTERACTIVE=0
  if [ $# -eq 0 ] && [ -z "${MPX_MENU_CHOICE:-}" ] && [ -t 0 ]; then
    MPX_MENU_INTERACTIVE=1
    MPX_UI_TTY=$(mpx_ui_tty) || MPX_UI_TTY=""
    mpx_fbcon_bind
    trap 'mpx_fbcon_restore' EXIT
    mpx_traps_rearm
  fi
  # First-run setup is skipped for uninstall (a dry-run must not mutate the card)
  # and when the caller already asked for setup/repair. Call setup outside a
  # &&/||/if list so set -e inside the wrapped tool still applies (R2).
  if [ "${MPX_MENU_NO_FIRSTRUN:-0}" != 1 ] && [ "${1:-}" != setup ] && [ "${1:-}" != repair ] && [ "${1:-}" != uninstall ] && needs_setup; then
    menu_say "first run: finishing the MisterPlex install"
    mpx_repair
    _setup_rc=$?
    if [ "$_setup_rc" != 0 ]; then
      menu_say "setup reported an error; choose Repair / Reinstall to try again"
    fi
  fi
  if [ $# -gt 0 ]; then run_item "$@"; return; fi
  while :; do
    k=$(menu_choose)
    [ -n "$k" ] || return 0
    run_item "$k"
    rc=$?
    [ -n "${MPX_MENU_CHOICE:-}" ] && return "$rc"
    # Cancelled uninstall/purge/settings: back to the main menu, no Done box.
    [ "$rc" = 75 ] && continue
    case "$k" in
      restart)
        # Short status line was already printed; no empty Done box.
        ;;
      repair)
        if [ "$rc" = 0 ]; then menu_msg "$(head -n 1 "$MENU_LAST" 2>/dev/null)"
        else menu_msg "$(head -n 1 "$MENU_LAST" 2>/dev/null)\n\nDetails: $MENU_LOG"; fi
        rm -f -- "$MENU_LAST" 2>/dev/null || true ;;
      uninstall)
        [ "$rc" = 0 ] && return 0
        menu_msg "That step failed (exit $rc). See the messages above." ;;
      *)
        if [ "$rc" = 0 ]; then menu_msg "Done."; else menu_msg "That step failed (exit $rc). See the messages above."; fi ;;
    esac
  done
}

# ---- mpx__settings: from scripts/configure-misterplex.sh (generated; do not edit here) ----
mpx__settings() (
# configure-misterplex.sh - guided setup for /media/fat/linux/misterplex.conf.
#
# Asks a few questions (or takes flags / environment for a non-interactive run)
# and writes the settings file. It starts from your current misterplex.conf,
# or from the default misterplex.conf.example when there is none (or with
# --fresh). The old file is always backed up first. Burned-in subtitles are
# always left off. Only settings the MiSTerPlex program reads are written.
set -eu

PROG=configure-misterplex.sh
ROOT="${ROOT:-}"
FAT="$ROOT/media/fat"
CONF="${MPX_CONF:-$FAT/linux/misterplex.conf}"
EXAMPLE="${MPX_CONF_EXAMPLE:-}"
DRY=0
ASK=1
FRESH=0

# Answers: flags win over environment. Empty = keep what the file has.
SERVER="${MPX_PLEX_SERVER:-}"
LINK="${MPX_PLEXTV_LINK:-}"
RASTER="${MPX_ANALOG_RASTER:-}"
SUBS="${MPX_SUBTITLES:-}"
SUBLANG="${MPX_SUBTITLE_LANG:-}"
UISIZE="${MPX_UI_SIZE:-}"
MARGIN="${MPX_UI_SAFE_MARGIN:-}"
NAME="${MPX_FRIENDLY_NAME:-}"

usage() {
  cat <<USAGE
Usage: sh $PROG [options]

Guided setup for MiSTerPlex. With no options it asks each question and shows
the current answer in [brackets]; press Enter to keep it.

  -y, --non-interactive  Do not ask; use only the options below.
  --server URL           Plex server, e.g. http://192.0.2.10:32400
                         (several: comma-separated). "none" clears it.
  --link on|off          Sign in on the TV with a plex.tv/link code (default on).
  --raster 480i|240p|auto|default
                         Analog output (MiSTerPlex core). "default" = the core's
                         own F12 setting. 240p needs the 240p-capable core.
  --subtitles on|off     Text subtitles on the TV (on = use --sub-lang).
  --sub-lang CODE        Subtitle language, e.g. en, de, fr.
  --ui-size normal|large On-screen menu size.
  --safe-margin 0-15     Keep menus this many percent inside the screen edge.
  --name NAME            Player name shown in the cast list.
  --conf FILE            Settings file (default: $CONF).
  --example FILE         Default settings to start from.
  --fresh                Start from the default settings, not your current file
                         (the player name is kept).
  --dry-run              Show the result, write nothing.
  -h, --help             Show this help.

Environment (same as the flags): MPX_PLEX_SERVER, MPX_PLEXTV_LINK,
MPX_ANALOG_RASTER, MPX_SUBTITLES, MPX_SUBTITLE_LANG, MPX_UI_SIZE,
MPX_UI_SAFE_MARGIN, MPX_FRIENDLY_NAME, MPX_CONF, MPX_CONF_EXAMPLE.

Burned-in subtitles stay off: every run writes BURN_SUBS_FIX=0 and AUTO_BURN=0,
and SUBTITLES=burn is changed to off.

Next step after setup: start MiSTerPlex (load MiSTerPlex), note the code on the
Ready screen (the row "plex.tv/link ABCD"), then go to https://plex.tv/link,
sign in and enter the code. Until the device is linked, Browse Plex on the TV
shows FETCH FAILED. Casting from the Plex app on your phone works without
linking. Linking is needed once; the sign-in is saved in the settings file.
USAGE
}

next_step() { # $1 = resulting settings file
  if [ -n "$(conf_get PLEXTV_TOKEN "$1")" ]; then
    say "next: this MiSTer is already signed in to Plex; no link code is needed."
  elif [ "$(conf_get PLEXTV_LINK "$1")" = 0 ]; then
    say "next: plex.tv linking is OFF (PLEXTV_LINK=0) and no Plex sign-in is saved."
    say "      Browse Plex on the TV will show FETCH FAILED; casting from the Plex app still works."
    say "      To link: run again with --link on."
  else
    say "next: start MiSTerPlex, note the code on the Ready screen (plex.tv/link ABCD),"
    say "      then link at https://plex.tv/link (sign in, enter the code)."
    say "      Until then Browse Plex on the TV shows FETCH FAILED. Casting from the Plex app works without it."
  fi
}

say()  { printf '%s\n' "$PROG: $*"; }
die()  { printf '%s\n' "$PROG: error: $*" >&2; exit 1; }

need() { [ $# -ge 2 ] || die "$1 needs a value"; }
while [ $# -gt 0 ]; do
  case "$1" in
    -y|--non-interactive) ASK=0; shift ;;
    --server) need "$@"; SERVER=$2; shift 2 ;;
    --link) need "$@"; LINK=$2; shift 2 ;;
    --raster) need "$@"; RASTER=$2; shift 2 ;;
    --subtitles) need "$@"; SUBS=$2; shift 2 ;;
    --sub-lang) need "$@"; SUBLANG=$2; shift 2 ;;
    --ui-size) need "$@"; UISIZE=$2; shift 2 ;;
    --safe-margin) need "$@"; MARGIN=$2; shift 2 ;;
    --name) need "$@"; NAME=$2; shift 2 ;;
    --conf) need "$@"; CONF=$2; shift 2 ;;
    --example) need "$@"; EXAMPLE=$2; shift 2 ;;
    --fresh) FRESH=1; shift ;;
    --dry-run) DRY=1; shift ;;
    -h|--help) usage; exit 0 ;;
    *) usage >&2; die "unknown option: $1" ;;
  esac
done
[ -t 0 ] || ASK=0

if [ -z "$EXAMPLE" ]; then
  here=$(CDPATH='' cd -- "$(dirname -- "$0")" && pwd)
  for e in "$FAT/misterplex/conf/misterplex.conf.example" "$here/../conf/misterplex.conf.example" \
           "$here/conf/misterplex.conf.example" "$here/../assets/misterplex.conf.example"; do
    if [ -f "$e" ]; then EXAMPLE=$e; break; fi
  done
fi

conf_get() { # last uncommented KEY= value
  [ -f "$2" ] || return 0
  awk -F= -v k="$1" '/^[ \t]*#/ {next} { x=$1; gsub(/^[ \t]+|[ \t]+$/, "", x)
    if (x == k) { v=substr($0, index($0, "=")+1); gsub(/\r/, "", v); gsub(/^[ \t"]+|[ \t"]+$/, "", v); last=v } }
    END { if (last != "") print last }' "$2"
}

# Start file.
if [ "$FRESH" = 0 ] && [ -f "$CONF" ]; then BASE=$CONF
elif [ -n "$EXAMPLE" ] && [ -f "$EXAMPLE" ]; then BASE=$EXAMPLE
else die "no settings file and no misterplex.conf.example found (use --example FILE)"
fi
say "starting from $BASE"

cur() { conf_get "$1" "$BASE"; }
# Print the current value, or $2 when conf_get prints nothing (an unset key
# is zero lines, so `value | sed 's/^$/default/'` never runs).
cur_or() { v=$(cur "$1"); if [ -n "$v" ]; then printf '%s\n' "$v"; else printf '%s\n' "$2"; fi; }
# Tests can force the question/form path with MPX_SETTINGS_ASK=1 (stdin need not be a tty).
[ "${MPX_SETTINGS_ASK:-0}" = 1 ] && ASK=1

ask() { # ask VAR "question" current
  if [ "$ASK" = 1 ] && eval "[ -z \"\${$1}\" ]"; then
    printf '%s [%s]: ' "$2" "$3"
    # shellcheck disable=SC2034 # ans is read through eval below
    read -r ans || ans=""
    eval "$1=\$ans"
  fi
}

settings_use_dialog() {
  if type use_dialog >/dev/null 2>&1; then
    use_dialog
    return
  fi
  case "${MPX_MENU_UI:-}" in
    text) return 1 ;;
    dialog) return 0 ;;
  esac
  command -v dialog >/dev/null 2>&1 && [ -t 0 ] && [ -t 1 ]
}

# Fill empty answer vars from the current file (or the shown default) so Save
# and a cancelled field keep what the form displayed.
settings_load_shown() {
  [ -n "$SERVER" ] || SERVER=$(cur PLEX_SERVERS)
  if [ -z "$LINK" ]; then
    if [ "$(cur PLEXTV_LINK)" = 0 ]; then LINK=off; else LINK=on; fi
  fi
  [ -n "$RASTER" ] || RASTER=$(cur_or ANALOG_RASTER default)
  if [ -z "$SUBS" ]; then
    case "$(cur SUBTITLE_LANG)" in ''|off) SUBS=off ;; *) SUBS=on ;; esac
  fi
  [ -n "$SUBLANG" ] || SUBLANG=$(cur_or SUBTITLE_LANG en)
  [ "$SUBLANG" = off ] && SUBLANG=en
  [ -n "$UISIZE" ] || UISIZE=$(cur_or UI_SIZE normal)
  [ -n "$MARGIN" ] || MARGIN=$(cur_or UI_SAFE_MARGIN 5)
  [ -n "$NAME" ] || NAME=$(cur FRIENDLY_NAME)
}

# Blue dialog form: a menu of items, each opens an inputbox or radiolist.
# Cancel returns 75 (no write). Save leaves the answer vars set and returns 0.
settings_form() {
  settings_load_shown
  while :; do
    sl_lab=$SUBLANG
    [ "$SUBS" = off ] && sl_lab="(off)"
    if type use_dialog >/dev/null 2>&1 && use_dialog; then
      # dlg (menu head) draws on the terminal and returns the pick on stdout, so this
      # capture keeps the blue dialog (the old 3>&1 1>&2 2>&3 form needed a tty stdout).
      _ch=$(dlg --title "Settings" --no-tags --cancel-label "Cancel" \
        --menu "Choose a setting, then Save." 20 72 12 \
        server "Plex server [$SERVER]" \
        link "plex.tv link [$LINK]" \
        raster "Analog output [$RASTER]" \
        subs "Text subtitles [$SUBS]" \
        sublang "Subtitle language [$sl_lab]" \
        uisize "Menu size [$UISIZE]" \
        margin "Safe margin [$MARGIN]" \
        name "Player name [$NAME]" \
        save "Save") || return 75
    else
      printf '\nSettings\n\n' >&2
      printf '  1) Plex server [%s]\n' "$SERVER" >&2
      printf '  2) plex.tv link [%s]\n' "$LINK" >&2
      printf '  3) Analog output [%s]\n' "$RASTER" >&2
      printf '  4) Text subtitles [%s]\n' "$SUBS" >&2
      printf '  5) Subtitle language [%s]\n' "$sl_lab" >&2
      printf '  6) Menu size [%s]\n' "$UISIZE" >&2
      printf '  7) Safe margin [%s]\n' "$MARGIN" >&2
      printf '  8) Player name [%s]\n' "$NAME" >&2
      printf '  9) Save\n  0) Cancel\n\nChoose 0-9: ' >&2
      read -r _n || return 75
      case "$_n" in
        1) _ch="server" ;; 2) _ch="link" ;; 3) _ch="raster" ;; 4) _ch="subs" ;;
        5) _ch="sublang" ;; 6) _ch="uisize" ;; 7) _ch="margin" ;; 8) _ch="name" ;;
        9) _ch="save" ;; *) return 75 ;;
      esac
    fi
    case "$_ch" in
      server)
        if type menu_inputbox >/dev/null 2>&1; then
          _v=$(menu_inputbox "Plex server address (blank = find it on the network or via plex.tv)" "$SERVER") && SERVER=$_v
        else
          printf 'Plex server address [%s]: ' "$SERVER" >&2; read -r _v || _v=$SERVER; SERVER=$_v
        fi ;;
      link)
        _on=off; _off=on; [ "$LINK" = on ] && _on=on && _off=off
        if type menu_radiolist >/dev/null 2>&1; then
          _v=$(menu_radiolist "Sign in on the TV with a plex.tv/link code?" on "on" "$_on" off "off" "$_off") && LINK=$_v
        else
          printf 'plex.tv link on/off [%s]: ' "$LINK" >&2; read -r _v || _v=$LINK; [ -n "$_v" ] && LINK=$_v
        fi ;;
      raster)
        _d=off _480=off _240=off _a=off
        case "$RASTER" in default) _d=on ;; 480i) _480=on ;; 240p) _240=on ;; auto) _a=on ;; *) _d=on ;; esac
        if type menu_radiolist >/dev/null 2>&1; then
          _v=$(menu_radiolist "Analog output (default = the core's F12 setting)" \
            default "default" "$_d" 480i "480i" "$_480" 240p "240p" "$_240" auto "auto" "$_a") && RASTER=$_v
        else
          printf 'Analog output 480i/240p/auto/default [%s]: ' "$RASTER" >&2; read -r _v || _v=$RASTER; [ -n "$_v" ] && RASTER=$_v
        fi ;;
      subs)
        _on=off; _off=on; [ "$SUBS" = on ] && _on=on && _off=off
        if type menu_radiolist >/dev/null 2>&1; then
          _v=$(menu_radiolist "Text subtitles?" on "on" "$_on" off "off" "$_off") && SUBS=$_v
        else
          printf 'Text subtitles on/off [%s]: ' "$SUBS" >&2; read -r _v || _v=$SUBS; [ -n "$_v" ] && SUBS=$_v
        fi ;;
      sublang)
        if type menu_inputbox >/dev/null 2>&1; then
          _v=$(menu_inputbox "Subtitle language (en, de, fr, ...)" "$SUBLANG") && SUBLANG=$_v
        else
          printf 'Subtitle language [%s]: ' "$SUBLANG" >&2; read -r _v || _v=$SUBLANG; [ -n "$_v" ] && SUBLANG=$_v
        fi ;;
      uisize)
        _n=off; _l=off
        case "$UISIZE" in large) _l=on ;; *) _n=on ;; esac
        if type menu_radiolist >/dev/null 2>&1; then
          _v=$(menu_radiolist "Menu size" normal "normal" "$_n" large "large" "$_l") && UISIZE=$_v
        else
          printf 'Menu size normal/large [%s]: ' "$UISIZE" >&2; read -r _v || _v=$UISIZE; [ -n "$_v" ] && UISIZE=$_v
        fi ;;
      margin)
        if type menu_inputbox >/dev/null 2>&1; then
          _v=$(menu_inputbox "Safe margin percent 0-15 (CRT: 5-10, HDMI: 0-5)" "$MARGIN") && MARGIN=$_v
        else
          printf 'Safe margin percent 0-15 [%s]: ' "$MARGIN" >&2; read -r _v || _v=$MARGIN; [ -n "$_v" ] && MARGIN=$_v
        fi ;;
      name)
        if type menu_inputbox >/dev/null 2>&1; then
          _v=$(menu_inputbox "Player name in the cast list (blank = automatic)" "$NAME") && NAME=$_v
        else
          printf 'Player name [%s]: ' "$NAME" >&2; read -r _v || _v=$NAME; NAME=$_v
        fi ;;
      save) break ;;
      *) return 75 ;;
    esac
  done
}

if [ "$ASK" = 1 ] && settings_use_dialog; then
  # Cancel: exit 0 when run by itself; the Scripts menu passes MPX_SETTINGS_CANCEL_RC=75 so
  # it goes straight back to the main menu with no Done box.
  settings_form || { say "settings cancelled"; exit "${MPX_SETTINGS_CANCEL_RC:-0}"; }
elif [ "$ASK" = 1 ]; then
  # Text questions (no dialog): show the same defaults as the form.
  ask SERVER "Plex server address (blank = find it on the network or via plex.tv)" "$(cur PLEX_SERVERS)"
  ask LINK "Sign in on the TV with a plex.tv/link code? on/off" "$( [ "$(cur PLEXTV_LINK)" = 0 ] && echo off || echo on)"
  ask RASTER "Analog output: 480i, 240p, auto, or default (core's F12 setting)" "$(cur_or ANALOG_RASTER default)"
  ask SUBS "Text subtitles on? on/off" "$( case "$(cur SUBTITLE_LANG)" in ''|off) echo off ;; *) echo on ;; esac)"
  if [ "$SUBS" = on ] || { [ -z "$SUBS" ] && [ -n "$(cur SUBTITLE_LANG)" ] && [ "$(cur SUBTITLE_LANG)" != off ]; }; then
    sl=$(cur SUBTITLE_LANG)
    case "$sl" in ''|off) sl=en ;; esac
    ask SUBLANG "Subtitle language (en, de, fr, ...)" "$sl"
  fi
  ask UISIZE "Menu size: normal or large" "$(cur_or UI_SIZE normal)"
  ask MARGIN "Safe margin percent 0-15 (CRT: 5-10, HDMI: 0-5)" "$(cur_or UI_SAFE_MARGIN 5)"
  ask NAME "Player name in the cast list (blank = automatic)" "$(cur FRIENDLY_NAME)"
fi

# Validate.
case "$SERVER" in
  ''|none) ;;
  *[!A-Za-z0-9.:/,_\[\]-]*) die "server address has odd characters: $SERVER" ;;
  http://*|https://*) ;;
  *) die "server must start with http:// or https:// (e.g. http://192.0.2.10:32400)" ;;
esac
case "$LINK" in ''|on|off|1|0) ;; *) die "--link must be on or off" ;; esac
case "$RASTER" in ''|480i|240p|auto|default) ;; *) die "--raster must be 480i, 240p, auto or default" ;; esac
case "$SUBS" in ''|on|off) ;; *) die "--subtitles must be on or off" ;; esac
case "$SUBLANG" in ''|*[!A-Za-z_-]*) [ -z "$SUBLANG" ] || die "bad subtitle language: $SUBLANG" ;; esac
case "$UISIZE" in ''|normal|large) ;; *) die "--ui-size must be normal or large" ;; esac
case "$MARGIN" in ''|[0-9]|1[0-5]) ;; *) die "--safe-margin must be 0-15" ;; esac
case "$NAME" in ''|*[!A-Za-z0-9._\ -]*) [ -z "$NAME" ] || die "player name: use letters, digits, space, . _ -" ;; esac

# Build the new file: KEY=VAL edits replace the last uncommented KEY= line,
# or append at the end. KEY with an empty VAL deletes uncommented KEY= lines.
# N9: TMP and OUT can hold the Plex tokens. umask 077 makes them 0600 from
# the moment they are created, and the trap removes them on exit or signal.
umask 077
TMP="${CONF}.mpx-cfg.$$"
OUT=""
trap 'rm -f -- "$TMP" ${OUT:+"$OUT"} ${OUT:+"$OUT.n"}' EXIT
trap 'exit 130' INT
trap 'exit 143' TERM
# N12: no predictable /tmp fallback; mktemp is required.
OUT=$(mktemp) || die "mktemp failed; cannot create a private temp file"
cp "$BASE" "$OUT"
setkv() {
  awk -v k="$1" -v v="$2" -v del="$3" '
    { lines[NR]=$0; s=$0; sub(/^[ \t]+/, "", s)
      if (s !~ /^#/) { split(s, a, "="); x=a[1]; gsub(/[ \t]+$/, "", x); if (x == k && index(s, "=")) hit[NR]=1; lastk = (x == k && index(s, "=")) ? NR : lastk } }
    END { done=0
      for (i=1; i<=NR; i++) {
        if (hit[i]) { if (del) continue; if (i == lastk) { print k "=" v; done=1 }; continue }
        print lines[i] }
      if (!del && !done) print k "=" v }' "$OUT" > "$OUT.n" && mv "$OUT.n" "$OUT"
}
set_key() { setkv "$1" "$2" ""; }
del_key() { setkv "$1" "" 1; }

case "$SERVER" in none) del_key PLEX_SERVERS ;; '') ;; *) set_key PLEX_SERVERS "$SERVER" ;; esac
case "$LINK" in on|1) set_key PLEXTV_LINK 1 ;; off|0) set_key PLEXTV_LINK 0 ;; esac
case "$RASTER" in default) del_key ANALOG_RASTER ;; '') ;; *) set_key ANALOG_RASTER "$RASTER" ;; esac
case "$SUBS" in
  off) set_key SUBTITLE_LANG off ;;
  on) set_key SUBTITLE_LANG "${SUBLANG:-en}" ;;
  '') [ -z "$SUBLANG" ] || set_key SUBTITLE_LANG "$SUBLANG" ;;
esac
[ -z "$UISIZE" ] || set_key UI_SIZE "$UISIZE"
[ -z "$MARGIN" ] || set_key UI_SAFE_MARGIN "$MARGIN"
# --fresh: carry the player name/id and the Plex sign-in over, so the
# device stays linked (values are copied file to file, never printed).
if [ "$FRESH" = 1 ] && [ -f "$CONF" ]; then
  for k in FRIENDLY_NAME PLAYER_ID PLEXTV_TOKEN PLEX_TOKEN PLEX_HOME_ID PLEX_HOME_TITLE PLEX_HOME_TOKEN; do
    old=$(conf_get "$k" "$CONF"); [ -z "$old" ] || set_key "$k" "$old"
  done
fi
[ -z "$NAME" ] || set_key FRIENDLY_NAME "$NAME"
# Burned-in subtitles stay off: opt-in only, by hand, for servers you own.
set_key BURN_SUBS_FIX 0
set_key AUTO_BURN 0
[ "$(conf_get SUBTITLES "$OUT")" != burn ] || set_key SUBTITLES off

if [ "$DRY" = 1 ]; then
  say "dry run: $CONF would get these settings:"
  for k in PLEX_SERVERS PLEXTV_LINK ANALOG_RASTER SUBTITLES SUBTITLE_LANG UI_SIZE UI_SAFE_MARGIN FRIENDLY_NAME PLAYER_ID BURN_SUBS_FIX AUTO_BURN; do
    printf '  %s=%s\n' "$k" "$(conf_get "$k" "$OUT")"
  done
  next_step "$OUT"
  exit 0
fi

mkdir -p "$(dirname "$CONF")"
if [ -f "$CONF" ]; then
  bak="$CONF.bak.$(date +%Y%m%d-%H%M%S)"
  cp -a "$CONF" "$bak"
  say "backed up the old settings to $bak"
  # Keep only the newest ${MPX_KEEP_BAK:-3} backups.
  n=0; for old in "$CONF".bak.[0-9]*; do [ -e "$old" ] && n=$((n + 1)); done
  for old in "$CONF".bak.[0-9]*; do   # globs sort; the stamp makes oldest first
    [ "$n" -gt "${MPX_KEEP_BAK:-3}" ] || break
    [ -e "$old" ] && rm -f -- "$old"; n=$((n - 1))
  done
fi
cp "$OUT" "$TMP" && mv -f "$TMP" "$CONF"
say "wrote $CONF"
say "restart to apply: sh $FAT/misterplex/bin/misterplexd-boot-rc3.sh stop; sh $FAT/misterplex/bin/misterplexd-boot-rc3.sh start"
next_step "$CONF"
)

# ---- mpx__setup: from mister-db/misterplex_setup.sh (generated; do not edit here) ----
mpx__setup() (
# misterplex_setup.sh - finish a MisterPlex install done by update_all / Downloader.
#
# Downloader installs every MisterPlex file it is allowed to write (the core, the
# /media/fat/misterplex tree). It refuses paths under /media/fat/linux and it never
# runs scripts, so this step (Scripts/configure-misterplex.sh runs it on first use and from
# Repair / Reinstall) does what install-misterplex.sh does after its copies:
#   - copies the CA bundle and the AirPlay / Cast helpers into /media/fat/linux
#   - creates /media/fat/linux/misterplex.conf from the example ONLY if it is missing
#     (an existing conf, including OVERSCAN and FRIENDLY_NAME, is never touched)
#   - removes the old PlexOB.rbf and a root MiSTerPlex.rbf copy once the
#     _Utility/MiSTerPlex.rbf on the card matches its shipped md5
#   - adds the one boot line to linux/user-startup.sh (via misterplexd-boot-rc3.sh install)
# Safe to run again (after every update_all that changed MisterPlex): nothing is
# added twice and the conf is never replaced. Run it from Scripts > configure-misterplex
# (Repair / Reinstall) or with: bash /media/fat/Scripts/configure-misterplex.sh setup
# exFAT: no modes, owners or symlinks; plain copies; scripts are run with sh.
set -eu
PROG=misterplex_setup.sh
ROOT="${ROOT:-}"
FAT="$ROOT/media/fat"
MPX="$FAT/misterplex"
LNX="$FAT/linux"
CONF="$LNX/misterplex.conf"
HOOK="$MPX/bin/misterplexd-boot-rc3.sh"
STAMP=$(date +%Y%m%d-%H%M%S)
say()  { printf '%s\n' "$PROG: $*"; }
warn() { printf '%s\n' "$PROG: warning: $*" >&2; }
die()  { printf '%s\n' "$PROG: error: $*" >&2; exit 1; }
md5of() { md5sum "$1" | cut -d' ' -f1; }
LEDGER="$MPX/.misterplex-created"
created() { mkdir -p "$MPX" && printf '%s\n' "${1#"$FAT"/}" >> "$LEDGER"; }

[ -d "$FAT" ] || die "$FAT not found; run this on the MiSTer"
[ -f "$HOOK" ] || die "$HOOK is missing; run update_all (with the MisterPlex database) first"
SUM="$MPX/cores/MiSTerPlex.rbf.md5"
CORE="$FAT/_Utility/MiSTerPlex.rbf"
[ -f "$SUM" ] || die "$SUM is missing; run update_all again"
want=$(awk 'NR==1 { print tolower($1); exit }' "$SUM")
[ -f "$CORE" ] || die "$CORE is missing; run update_all again"
[ "$(md5of "$CORE")" = "$want" ] || die "$CORE does not match $SUM; run update_all again"

# 1. Stop a running copy (the new files are already in place).
say "stopping a running MisterPlex (if any)"
env ROOT="$ROOT" sh "$HOOK" stop || warn "stop returned an error; continuing"

# 2. /media/fat/linux files (Downloader cannot write there).
mkdir -p "$LNX"
src="$MPX/linux/misterplex-cacert.pem"
if [ -f "$src" ]; then
  if [ -f "$LNX/misterplex-cacert.pem" ] && cmp -s "$src" "$LNX/misterplex-cacert.pem"; then
    say "CA bundle already current"
  else
    if [ -f "$LNX/misterplex-cacert.pem" ]; then
      cp "$LNX/misterplex-cacert.pem" "$LNX/misterplex-cacert.pem.bak.$STAMP"; created "$LNX/misterplex-cacert.pem.bak.$STAMP"
    fi
    cp "$src" "$LNX/misterplex-cacert.pem" || die "could not install $LNX/misterplex-cacert.pem"
    say "installed $LNX/misterplex-cacert.pem"
  fi
fi
# Install both airplay and gcast helper trees (if staged under misterplex/linux/).
for h in airplay gcast; do
  [ -d "$MPX/linux/$h" ] || continue
  say "installing the $h helper -> $LNX/$h"
  mkdir -p "$LNX/$h" || die "could not create $LNX/$h"
  cp -RL "$MPX/linux/$h/." "$LNX/$h/" || die "could not install the $h helper to $LNX/$h"
  # Manifest so uninstall-misterplex.sh removes only these files.
  (cd "$MPX/linux/$h" && { find . -type d ! -name . | sed 's|^\./|d |'
    find . \( -type f -o -type l \) | sed 's|^\./|f |'; }) > "$LNX/$h/.misterplex-files"
  if [ -f "$LNX/$h/MD5SUMS" ]; then
    (cd "$LNX/$h" && md5sum -c MD5SUMS >/dev/null) || die "$LNX/$h: MD5SUMS check failed"
  fi
done
# Dest helpers must be present, or restorable from misterplex/linux/ staging.
# A tar install now leaves that staging; an older tar card without it cannot be
# silently reported as repaired.
if [ ! -f "$LNX/misterplex-cacert.pem" ]; then
  die "CA bundle is missing ($LNX/misterplex-cacert.pem) and there is no copy at $MPX/linux/misterplex-cacert.pem to restore"
fi
if [ ! -f "$LNX/airplay/airplay_xcode.py" ]; then
  die "AirPlay helper is missing ($LNX/airplay/airplay_xcode.py) and there is no copy under $MPX/linux/airplay to restore"
fi

# 2b. Clean up what older installs put on the card and the runtime set no longer ships
# (v1.0.0 package install or an older db). Same list as scripts/install-misterplex.sh 2b.
# Fixed paths only. Never touches linux/misterplex.conf, OVERSCAN, backup/, keys, caches or logs.
for d in "$MPX/licenses" "$MPX/docs" "$MPX/scripts"; do
  [ -d "$d" ] || continue
  rm -rf -- "$d" && say "removed $d (not needed on the MiSTer)"
done
for f in LICENSE NOTICE README.md README.txt RELEASE-NOTES.md \
         bin/misterplex_core_watch.sh bin/misterplex_pair_conf.sh bin/misterplex_named_rbf.sh \
         bin/push_frame bin/set_status plexui/LICENSE-Roboto.txt run-gcast-xcode.sh \
         bin/install-misterplex.sh bin/configure-misterplex.sh bin/uninstall-misterplex.sh \
         bin/misterplex_plex.sh bin/misterplex_spelunkr.sh bin/misterplex_restart_manual.sh; do
  [ -f "$MPX/$f" ] || continue
  rm -f -- "$MPX/$f" && say "removed $MPX/$f (not needed on the MiSTer)"
done
# The old separate db Scripts entry; setup now lives in Scripts/configure-misterplex.sh.
[ ! -f "$FAT/Scripts/misterplex_setup.sh" ] || { rm -f -- "$FAT/Scripts/misterplex_setup.sh" && say "removed the old $FAT/Scripts/misterplex_setup.sh"; }
# linux/gcast, once linux/airplay is in place: the files in its .misterplex-files manifest, else the
# files its MD5SUMS lists, and always the five files every older package put there, so nothing is left
# behind. Other files there are the user's and are kept. Same rules as scripts/install-misterplex.sh.
GC="$LNX/gcast"
gc_safe() { case "$1" in ''|/*|.|..|./*|../*|*/./*|*/../*|*/.|*/..) return 1 ;; esac; }
gc_rm() { gc_safe "$1" || return 0; { [ -f "$GC/$1" ] || [ -L "$GC/$1" ]; } || return 0; rm -f -- "$GC/$1"; }
if [ ! -d "$MPX/linux/gcast" ] && [ -d "$GC" ] && [ ! -L "$GC" ] && [ -f "$LNX/airplay/airplay_xcode.py" ]; then
  gc_dirs=""; gc_list=""
  if [ -f "$GC/.misterplex-files" ] && [ ! -L "$GC/.misterplex-files" ]; then
    gc_list=$(sed -n 's/^f //p' "$GC/.misterplex-files")
    gc_dirs=$(awk '$1 == "d" { print length($0) "\t" substr($0, 3) }' "$GC/.misterplex-files" | sort -rn | cut -f2-)
  elif [ -f "$GC/MD5SUMS" ] && [ ! -L "$GC/MD5SUMS" ]; then
    gc_list=$(sed -n 's/^[0-9a-fA-F]\{32\}[ *][ *]*//p' "$GC/MD5SUMS")
  fi
  printf '%s\n' "$gc_list" | while IFS= read -r rel; do gc_rm "$rel"; done
  for f in MD5SUMS ffmpeg ffprobe gcast_xcode.py run-gcast-xcode.sh .misterplex-files; do gc_rm "$f"; done
  printf '%s\n' "$gc_dirs" | while IFS= read -r rel; do gc_safe "$rel" && rmdir -- "$GC/$rel" 2>/dev/null || true; done
  if rmdir -- "$GC" 2>/dev/null; then say "removed the old helper copy $GC"; else say "kept $GC: it holds files MisterPlex did not put there"; fi
fi

# 2c. yt-dlp (YouTube): replace a missing or older card copy with the shipped zip; a
# matching or newer copy stays (update_ytdlp.sh YTDLP_IF_OLDER). The boot script only
# unpacks when none is there, so an old copy used to stay forever. No shipped zip: an
# online update in the background (log /tmp/misterplex-ytdlp.log).
YUPD="$MPX/bin/update_ytdlp.sh"; YZIP="$MPX/bin/yt-dlp_linux_armv7l.zip"; YDEST="$LNX/misterplex/yt-dlp"
if [ -f "$YUPD" ] && [ -f "$YZIP" ]; then
  say "checking yt-dlp against the shipped copy"
  env YTDLP_IF_OLDER=1 YTDLP_LOCAL_ZIP="$YZIP" YTDLP_DEST="$YDEST" MPX_YT_CACHE_DIR="$MPX/yt-cache" sh "$YUPD" \
    || warn "yt-dlp refresh failed; YouTube may not play until the daily online update"
elif [ -f "$YUPD" ] && [ "${MPX_YTDLP_ONLINE:-1}" = 1 ]; then
  say "no shipped yt-dlp; updating it online in the background (log: $ROOT/tmp/misterplex-ytdlp.log)"
  mkdir -p "$ROOT/tmp" 2>/dev/null || true
  ( env YTDLP_DEST="$YDEST" MPX_CA_BUNDLE="$LNX/misterplex-cacert.pem" MPX_YT_CACHE_DIR="$MPX/yt-cache" \
      sh "$YUPD" >> "$ROOT/tmp/misterplex-ytdlp.log" 2>&1 < /dev/null & )
fi

# 3. Settings: create once, never replace.
if [ -f "$CONF" ]; then
  say "keeping your settings: $CONF"
elif [ -f "$MPX/conf/misterplex.conf.example" ]; then
  cp "$MPX/conf/misterplex.conf.example" "$CONF"; say "created $CONF from the default settings"
else
  warn "no misterplex/conf/misterplex.conf.example; the daemon will use built-in defaults"
fi

# 4. One core only, in _Utility. Same rules as install-misterplex.sh.
BAKD="$MPX/backup"
for b in "$CORE".bak.[0-9]* "$FAT/MiSTerPlex.rbf".bak.[0-9]*; do
  [ -f "$b" ] || continue; mkdir -p "$BAKD"; mv -f "$b" "$BAKD/"
done
if [ -f "$FAT/MiSTerPlex.rbf" ]; then
  if [ "$(md5of "$FAT/MiSTerPlex.rbf")" = "$want" ]; then
    rm -f -- "$FAT/MiSTerPlex.rbf" && say "removed the root core copy $FAT/MiSTerPlex.rbf"
  else
    mkdir -p "$BAKD"; mv -f "$FAT/MiSTerPlex.rbf" "$BAKD/MiSTerPlex.rbf.root.$STAMP"
    say "moved an older root core copy to $BAKD/MiSTerPlex.rbf.root.$STAMP"
  fi
fi
# The core was renamed from PlexOB.rbf. Only these four exact paths; no globs.
case "$FAT" in ''|/|//*|*\**|*\?*) die "refusing to clean core files under $FAT" ;; esac
for old in "$FAT/PlexOB.rbf" "$FAT/_Utility/PlexOB.rbf" "$FAT/_Console/PlexOB.rbf" "$FAT/cores/PlexOB.rbf"; do
  [ -f "$old" ] || continue
  rm -f -- "$old" && say "removed the old core $old (renamed to MiSTerPlex.rbf)"
done

# 5. Best effort exec bits (ignored on exFAT; everything is started with sh or works without).
chmod +x "$MPX/bin/"*.sh "$MPX/bin/misterplexd" "$MPX/bin/misterplexd-spelunkr" 2>/dev/null || true

# 6. Boot hook: one line in linux/user-startup.sh, never twice.
say "enabling start at boot"
env ROOT="$ROOT" sh "$HOOK" install

say "done. Reboot the MiSTer, then load MiSTerPlex from _Utility. Settings: $CONF"
say "link it: note the code on the Ready screen, go to https://plex.tv/link, sign in and enter it."
say "to change settings, repair or uninstall: Scripts > configure-misterplex"
)

# ---- mpx__uninstall: from scripts/uninstall-misterplex.sh (generated; do not edit here) ----
mpx__uninstall() (
# uninstall-misterplex.sh - undo install-misterplex.sh on a MiSTer.
#
# Runs ON the MiSTer (or against a fake tree with ROOT=<dir> for tests).
#   1. Runs misterplexd-boot-rc3.sh uninstall: stops misterplexd and removes
#      its line from /media/fat/linux/user-startup.sh.
#   2. Deletes what the installer created: the core (_Utility and any root
#      copy), linux/misterplex-cacert.pem, the program files in
#      /media/fat/misterplex/ (bin scripts docs licenses plexui conf, warm helper
#      and its cache/endpoint files) and the
#      .bak.<time> copies listed in the install ledger misterplex/.misterplex-created.
#      In linux/airplay and linux/gcast only the files listed in the install
#      manifest (.misterplex-files, or MD5SUMS from older installs) are removed;
#      other files there, and the folders holding them, are kept.
#      Files MisterPlex itself generates at run time go too: the AirPlay/Cast helper
#      copies the boot script makes in misterplex/ (airplay_xcode.py, gcast_xcode.py,
#      run-airplay-xcode.sh, run-gcast-xcode.sh), the yt-dlp it unpacks and updates in
#      linux/misterplex/ (yt-dlp/, yt-dlp.update-stamp), and the fixed helper names older
#      packages put in linux/gcast (kept there: any other file, and the folder then).
#   3. Keeps your settings and all other user/runtime data under misterplex/
#      (airplay_key.pem, yt_screen_id, reports/, ca/, ...) unless --purge:
#      /media/fat/linux/misterplex.conf, /media/fat/misterplex/misterplex.conf
#      (fallback conf), /media/fat/misterplex/identity and
#      /media/fat/misterplex/backup/ (cores the installer moved aside).
#      Lines other tools wrote to user-startup.sh are untouched.
# exFAT safe: no chmod, chown or symlinks; the boot script is run with sh.
set -eu

PROG=uninstall-misterplex.sh
DRY=0
KEEP_CORE=0
PURGE=0
ROOT="${ROOT:-}"

usage() {
  cat <<USAGE
Usage: sh $PROG [--dry-run] [--keep-core] [--purge]

Turns off MiSTerPlex at boot and removes everything the installer created.

  --dry-run         Print every step, change nothing.
  --keep-core       Leave MiSTerPlex.rbf in place.
  --purge           Also remove the settings and all of misterplex/ (identity,
                    backup/, keys, reports) and the user-startup.sh .bak copies
                    the installer made.
  --remove-program  Accepted for older notes; the program is always removed.
  -h, --help        Show this help.

Settings, identity and moved-aside cores are kept unless --purge.
USAGE
}

say()  { printf '%s\n' "$PROG: $*"; }
warn() { printf '%s\n' "$PROG: warning: $*" >&2; }
die()  { printf '%s\n' "$PROG: error: $*" >&2; exit 1; }
run()  {
  if [ "$DRY" = 1 ]; then printf '  [dry-run] %s\n' "$*"; else "$@"; fi
}

while [ $# -gt 0 ]; do
  case "$1" in
    --dry-run) DRY=1; shift ;;
    --keep-core) KEEP_CORE=1; shift ;;
    --purge) PURGE=1; shift ;;
    --remove-program) shift ;;
    -h|--help) usage; exit 0 ;;
    *) usage >&2; die "unknown option: $1" ;;
  esac
done

FAT="$ROOT/media/fat"
[ -d "$FAT" ] || die "$FAT not found (is this a MiSTer?)"
case "$FAT" in *\**|*\?*) die "refusing to clean under $FAT" ;; esac
LNX="$FAT/linux"
MPX="$FAT/misterplex"
HOOK="$MPX/bin/misterplexd-boot-rc3.sh"
gone() { # gone PATH...: delete what install-misterplex.sh created (dirs too)
  for x in "$@"; do
    [ -e "$x" ] || [ -L "$x" ] || continue
    say "removing $x"
    run rm -rf -- "$x"
  done
}

# 1. Stop the daemon and remove the boot line (run with sh: no x bit on exFAT).
if [ -f "$HOOK" ]; then
  say "stopping MiSTerPlex and removing its boot line"
  run env ROOT="$ROOT" sh "$HOOK" uninstall || warn "boot script uninstall returned an error; continuing"
else
  warn "$HOOK not found; the MiSTerPlex line in $LNX/user-startup.sh stays (remove it by hand)"
fi

# 2. The core (both places older installers used) and the backups next to it.
if [ "$KEEP_CORE" = 0 ]; then
  gone "$FAT/MiSTerPlex.rbf" "$FAT/_Utility/MiSTerPlex.rbf"   # .bak copies only via the ledger
fi

# 3. The CA bundle, and in airplay/gcast only the files install put there.
gone "$LNX/misterplex-cacert.pem"
gone "$FAT/Scripts/configure-misterplex.sh" "$FAT/Scripts/misterplex_setup.sh"   # the Scripts menu entry (installer / update_all)
# P2: the Spelunkr header (moov) cache -- pure performance cache, never user data, always
# removed (not gated by --purge).
gone "$LNX/misterplex-cache"
helper_files() { # helper_files DIR: remove only installer-listed files in DIR
  d=$1; m="$d/.misterplex-files"
  [ -d "$d" ] || return 0
  if [ -L "$d" ]; then warn "$d is a symlink; left as is"; return 0; fi
  base=$(readlink -f -- "$d") || { warn "cannot resolve $d; left as is"; return 0; }
  if [ -f "$m" ] && [ ! -L "$m" ]; then
    list=$(sed -n 's/^f //p' "$m"); dirs=$(sed -n 's/^d //p' "$m" | sort -r)
  elif [ -f "$d/MD5SUMS" ] && [ ! -L "$d/MD5SUMS" ]; then
    list=$(sed -n 's/^[0-9a-fA-F]\{32\}[ *][ *]*//p' "$d/MD5SUMS"); dirs=""
  else
    warn "$d has no install manifest; left as is"; return 0
  fi
  printf '%s\n' "$list" | while IFS= read -r f; do
    safe_entry "$d" "$base" "$f" || continue
    p="$d/$f"
    if [ -L "$p" ]; then say "removing link $p"; run rm -f -- "$p"   # unlink only, never follow
    elif [ -f "$p" ]; then say "removing $p"; run rm -f -- "$p"
    elif [ -e "$p" ]; then warn "skipped $p: not a file"
    fi
  done
  run rm -f -- "$m" "$d/MD5SUMS"
  printf '%s\n' "$dirs" | while IFS= read -r f; do
    safe_entry "$d" "$base" "$f" || continue
    [ -L "$d/$f" ] && { warn "skipped $d/$f: symlink, not a folder"; continue; }
    [ "$DRY" = 1 ] || rmdir -- "$d/$f" 2>/dev/null || true
  done
  if [ "$DRY" = 0 ] && rmdir -- "$d" 2>/dev/null; then say "removed empty $d"
  elif [ -d "$d" ]; then say "kept $d (holds files the installer did not create)"; fi
}
safe_entry() { # safe_entry DIR REALDIR ENTRY: 0 if DIR/ENTRY stays inside DIR
  [ -n "$3" ] || return 1
  case "$3" in /*) warn "skipped manifest entry '$3' in $1: absolute path"; return 1 ;; esac
  case "/$3/" in
    */../*|*/./*) warn "skipped manifest entry '$3' in $1: '..' or '.' component"; return 1 ;;
  esac
  par=$(dirname -- "$1/$3")
  [ -e "$1/$3" ] || [ -L "$1/$3" ] || return 1
  rp=$(readlink -f -- "$par" 2>/dev/null) || { warn "skipped $1/$3: cannot resolve its folder"; return 1; }
  case "$rp/" in
    "$2"/*) return 0 ;;
    *) warn "skipped $1/$3: its folder resolves outside $1 ($rp)"; return 1 ;;
  esac
}
helper_files "$LNX/airplay"; helper_files "$LNX/gcast"
# Older packages' fixed helper names in linux/gcast (some not in its manifest, e.g. an
# airplay_xcode.py copy). Only these exact names; other files and a symlinked folder stay.
GC="$LNX/gcast"
if [ -d "$GC" ] && [ ! -L "$GC" ]; then
  for f in airplay_xcode.py gcast_xcode.py run-airplay-xcode.sh run-gcast-xcode.sh ffmpeg ffprobe MD5SUMS .misterplex-files; do
    { [ -f "$GC/$f" ] || [ -L "$GC/$f" ]; } && gone "$GC/$f"
  done
  if [ "$DRY" = 0 ] && rmdir -- "$GC" 2>/dev/null; then say "removed empty $GC"; fi
fi

# Generated at run time by MisterPlex (not user data): the helper copies the boot script
# makes in misterplex/ from linux/airplay, and the yt-dlp it unpacks/updates under
# linux/misterplex/ (yt-dlp/, yt-dlp.prev/, its stamp, lock and temp dirs).
# linux/misterplex/identity (older installs) is the user's: kept unless --purge.
gone "$MPX/airplay_xcode.py" "$MPX/gcast_xcode.py" "$MPX/run-airplay-xcode.sh" "$MPX/run-gcast-xcode.sh"
LMPX="$LNX/misterplex"
if [ -d "$LMPX" ] && [ ! -L "$LMPX" ]; then
  if [ "$PURGE" = 1 ]; then
    gone "$LMPX"
  else
    gone "$LMPX/yt-dlp" "$LMPX/yt-dlp.prev" "$LMPX/yt-dlp.update-stamp" "$LMPX/.yt-dlp-sweep.lock" \
         "$LMPX"/.yt-dlp-dl.* "$LMPX"/.yt-dlp-new.* "$LMPX"/.yt-dlp-flat.*
    if [ "$DRY" = 0 ] && rmdir -- "$LMPX" 2>/dev/null; then say "removed empty $LMPX"
    elif [ -d "$LMPX" ]; then say "kept $LMPX (--purge removes it)"; fi
  fi
fi

# Shipped worker plus the warm-helper runtime dir (cache, abstract marker, lock, log).
LEGACY_WARM="$FAT/_Utilities/misterplex"
for warm in "$MPX" "$LEGACY_WARM"; do
  gone "$warm/yt_warm_helper.py" "$warm/yt_warm_helper.py.bak" "$warm"/yt_warm_helper.py.bak.* \
       "$warm/yt-warm.sock" \
       "$warm/yt-warm.sock.lock" "$warm/yt-warm.sock.log" "$warm/yt-cache"
done
if [ "$DRY" = 0 ]; then
  rmdir "$LEGACY_WARM" "$FAT/_Utilities" 2>/dev/null || true
fi

# 4. Backups this install made, from its ledger (misterplex/.misterplex-created). Nothing
#    else named .bak is touched. user-startup .bak copies go only with --purge.
# #353: suffix after .bak. is only YYYYMMDD-HHMMSS or 1-3 digits (N<=999).
ledger_bak_ok() {
  case "$1" in
    misterplex/bin.bak.*|linux/misterplex.conf.bak.*|linux/misterplex-cacert.pem.bak.*|\
    linux/user-startup.sh.bak.*|linux/_user-startup.sh.bak.*) ;;
    *) return 1 ;;
  esac
  case "$1" in */*/*|../*|/*) return 1 ;; esac
  suf=${1##*.bak.}
  case "$suf" in
    [0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]-[0-9][0-9][0-9][0-9][0-9][0-9]) return 0 ;;
    [0-9]|[0-9][0-9]|[0-9][0-9][0-9]) return 0 ;;
    *) return 1 ;;
  esac
}
L="$MPX/.misterplex-created"
if [ -f "$L" ] && [ ! -L "$L" ] && fatreal=$(readlink -f -- "$FAT"); then
  [ "$DRY" = 1 ] || rm -f -- "$L.keep"
  while IFS= read -r rel; do
    # #349/#353: only installer .bak copies (backup() targets + hook's user-startup), bounded suffix.
    if ! ledger_bak_ok "$rel"; then
      say "ledger entry outside the package prefixes, skipped: $rel"
      continue
    fi
    case "$rel" in
      linux/user-startup.sh.bak.*|linux/_user-startup.sh.bak.*)
        if [ "$PURGE" = 0 ]; then   # kept; stays in the ledger so a later --purge can remove it
          [ -e "$FAT/$rel" ] && printf '%s\n' "$rel" >> "$L.keep"
          continue
        fi ;;
    esac
    safe_entry "$FAT" "$fatreal" "$rel" || continue
    gone "$FAT/$rel"
  done < "$L"
else
  warn "no install ledger ($L); no .bak copies removed"
fi

# 5. The program folder. Plain uninstall removes only the folders install copies in;
#    everything else under misterplex/ (conf, identity, backup/, keys, ca/, reports/,
#    yt_screen_id, ...) is user or runtime data and stays. --purge removes the folder.
if [ "$PURGE" = 1 ]; then
  gone "$MPX"
elif [ -d "$MPX" ]; then
  for d in bin scripts docs licenses plexui conf cores linux; do gone "$MPX/$d"; done
  if [ -s "$L.keep" ] && [ "$DRY" = 0 ]; then mv -f -- "$L.keep" "$L"   # only the kept user-startup .bak entries
  else gone "$L"; rm -f -- "$L.keep"; fi
  for x in "$MPX"/* "$MPX"/.[!.]*; do
    [ -e "$x" ] || [ -L "$x" ] || continue
    say "kept $x (--purge removes it)"
  done
  [ "$DRY" = 1 ] || rmdir -- "$MPX" 2>/dev/null || true
fi

# 6. Settings: kept unless --purge; the installer's .bak copies of them go.
if [ "$PURGE" = 1 ]; then
  gone "$LNX/misterplex.conf"
elif [ -f "$LNX/misterplex.conf" ]; then
  say "kept your settings: $LNX/misterplex.conf (--purge removes it)"
fi
say "done. Reboot the MiSTer to finish. To reinstall, use Scripts > configure-misterplex and choose Repair / Reinstall."
)

menu_main "$@"
